/**
* Minimal i18n. Add `en.ts` with the same shape (typed as `Dict`) and register it
* here to support English; the active locale can then come from settings.
*/
var dictionaries = { ro };
var locale = "ro";
var useT = () => dictionaries[locale] ?? ro;
/** Replace {placeholders} in a string. */
var fmt = (s, vars) => s.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ""));
var formatMoney = (n, currency = "RON") => currency === "RON" ? `${new Intl.NumberFormat("ro-RO").format(n)} lei` : new Intl.NumberFormat("ro-RO", {
	style: "currency",
	currency
}).format(n);
var formatDate = (iso) => new Intl.DateTimeFormat("ro-RO", {
	day: "numeric",
	month: "short",
	year: "numeric"
}).format(new Date(iso));
var formatRelative = (iso) => {
	const diff = Date.now() - new Date(iso).getTime();
	const m = Math.round(diff / 6e4);
	if (m < 60) return `acum ${Math.max(1, m)} min`;
	const h = Math.round(m / 60);
	if (h < 24) return `acum ${h} ${h === 1 ? "oră" : "ore"}`;
	const d = Math.round(h / 24);
	return `acum ${d} ${d === 1 ? "zi" : "zile"}`;
};
